<script module lang="ts">
/**
 * A timestamp such as "2h ago", or the moment itself, in a `<time>` element (`design/components/relative-time.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/relative-time.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { devWarning, joinSlot, relativeTimePhrase, watchEffect } from '@polymorph/svelte'

export interface RelativeTimeMessages {
  both: (moment: string, distance: string) => string
}

export interface RelativeTimeProps {
  /**
   * Intl's `style` without `short`, which looks like `narrow`. Named `format` (NumberInput's
   * word) because the governed-props law and `no-raw-styles` read any JSX `style` as raw CSS. In
   * the absolute form it is the date's length: `narrow` is Intl's `medium` date ("Aug 4, 2026"),
   * `long` its `long` date.
   */
  format?: 'long' | 'narrow'
  /**
   * The locale `Intl` formats with; defaults to the page's own.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: RelativeTimeMessages
  /**
   * What it says: the distance from now (`relative`, the default), the moment itself
   * (`absolute`, "Aug 4, 2026, 2:05 PM"), or both, joined by `messages.both` ("Aug 4, 2026, 2:05
   * PM (2h ago)"), for a place where the exact moment matters. An instant is written in the time
   * zone of whatever renders the member: the reader's in a browser, the server's on a server.
   */
  mode?: 'both' | 'relative' | 'absolute'
  /**
   * Intl's `numeric` option. `always` (the default) suits scanned queue metadata ("1 day ago");
   * prose surfaces pass `auto` for "yesterday".
   */
  numeric?: 'always' | 'auto'
  /**
   * ISO-8601 with the chart tier's calendar-date rules (`docs/charts.md`): a date-only string is
   * a **calendar date**, not shifted by timezone ("2026-08-04" is the 4th everywhere), and a
   * full timestamp keeps its offset.
   */
  value: string
}
</script>

<script lang="ts">
let {
  format = 'narrow',
  locale,
  messages,
  mode = 'relative',
  numeric = 'always',
  value,
}: RelativeTimeProps = $props()
const joined = joinSlot(undefined, () => ({}))
const phrase = $derived(relativeTimePhrase(value, { locale, numeric, format, mode, messages }))
const effect1 = () => {
  devWarning(phrase === null, `RelativeTime could not parse "${value}" — rendering nothing.`)
}
watchEffect(effect1, { watch: () => phrase })
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if phrase !== null}<time datetime={value} data-member="relative-time">{phrase}</time>{/if
}{/if
}{@render joined.end?.()}
